-- B-W1 Revenue Including Tax = sum(total_including_tax) over fact_sale
-- Generated by build_metric_sql.py; edit the generator, not this file.
WITH base AS (
  SELECT f.total_excluding_tax, f.total_including_tax, f.profit, f.quantity, f.wwi_invoice_id,
         f.invoice_date, d.calendar_year, d.month_start_date, d.fiscal_year,
         dd.calendar_year AS delivery_year,
         c.category AS customer_category, c.customer AS customer_name,
         bt.customer AS bill_to_customer_name,
         ci.sales_territory, ci.state_province,
         si.wwi_stock_item_id, si.stock_item, si.color,
         e.employee AS salesperson
  FROM wwi.fact_sale f
  JOIN wwi.dim_date d ON d.date_key = f.invoice_date
  LEFT JOIN wwi.dim_date dd ON dd.date_key = f.delivery_date
  JOIN wwi.dim_customer c ON c.customer_key = f.customer_key
  JOIN wwi.dim_customer bt ON bt.customer_key = f.bill_to_customer_key
  JOIN wwi.dim_city ci ON ci.city_key = f.city_key
  JOIN wwi.dim_stock_item si ON si.stock_item_key = f.stock_item_key
  JOIN wwi.dim_employee e ON e.employee_key = f.salesperson_key
)
SELECT grain, measure, member_1, member_2, member_3, value
FROM (
  SELECT 'total' AS grain, 'B-W1' AS measure, CAST(NULL AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  UNION ALL
  SELECT 'year' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year
  UNION ALL
  SELECT 'month' AS grain, 'B-W1' AS measure, CAST(month_start_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY month_start_date
  UNION ALL
  SELECT 'day' AS grain, 'B-W1' AS measure, CAST(invoice_date AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY invoice_date
  UNION ALL
  SELECT 'fiscal_year' AS grain, 'B-W1' AS measure, CAST(fiscal_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY fiscal_year
  UNION ALL
  SELECT 'delivery_year' AS grain, 'B-W1' AS measure, CAST(delivery_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY delivery_year
  UNION ALL
  SELECT 'year_customer_category' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(customer_category AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, customer_category
  UNION ALL
  SELECT 'year_customer' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(customer_name AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, customer_name
  UNION ALL
  SELECT 'year_bill_to_customer' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(bill_to_customer_name AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, bill_to_customer_name
  UNION ALL
  SELECT 'year_sales_territory' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(sales_territory AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, sales_territory
  UNION ALL
  SELECT 'year_state_province' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(state_province AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, state_province
  UNION ALL
  SELECT 'year_stock_item' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(stock_item AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, stock_item
  UNION ALL
  SELECT 'year_color' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(color AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, color
  UNION ALL
  SELECT 'year_salesperson' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(salesperson AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base
  GROUP BY calendar_year, salesperson
  UNION ALL
  SELECT 'year_stock_group' AS grain, 'B-W1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(g.stock_group_name AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, SUM(total_including_tax) AS value
  FROM base JOIN wwi.bridge_stock_item_group b ON b.wwi_stock_item_id = base.wwi_stock_item_id JOIN wwi.dim_stock_group g ON g.stock_group_id = b.stock_group_id
  GROUP BY calendar_year, g.stock_group_name
) r
ORDER BY grain, measure, member_1 NULLS FIRST, member_2 NULLS FIRST, member_3 NULLS FIRST
